/**
 * @title A sidebar with a collapsible file tree
 * @description Changed files on top, the project's folders below. Folders open and close; files are links.
 * @route /editor
 */
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { AppSidebar } from "@/components/app-sidebar";
import { SiteHeader } from "@/components/site-header";
import { PagePlaceholder } from "@/components/page-placeholder";

export default function Page() {
  return (
    <SidebarProvider>
      <AppSidebar />
      <SidebarInset>
        <SiteHeader crumbs={[{ label: "components", href: "#" }, { label: "ui", href: "#" }, { label: "button.tsx" }]} />
        <PagePlaceholder title="button.tsx" />
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";
import { ChevronRight, File, Folder } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import {
  Sidebar, SidebarContent, SidebarGroup, SidebarGroupContent, SidebarGroupLabel, SidebarMenu, SidebarMenuBadge, SidebarMenuButton,
  SidebarMenuItem, SidebarMenuSub, SidebarRail, useDisclosure,
} from "@/components/ui/sidebar";

type Node = string | [string, ...Node[]];
const changes = [{ file: "README.md", state: "M" }, { file: "api/hello/route.ts", state: "U" }, { file: "app/layout.tsx", state: "M" }];
const tree: Node[] = [
  ["app", ["api", ["hello", "route.ts"]], "page.tsx", "layout.tsx", ["blog", "page.tsx"]],
  ["components", ["ui", "button.tsx", "card.tsx"], "header.tsx", "footer.tsx"],
  ["lib", ["util.ts"]],
  ["public", "favicon.ico", "vercel.svg"],
  ".eslintrc.json", ".gitignore", "next.config.js", "tailwind.config.js", "package.json", "README.md",
];
const stateLabel = { M: "modified", U: "untracked" } as const;

function TreeNode({ node }: { node: Node }) {
  const isFolder = Array.isArray(node);
  const [name, ...children] = isFolder ? node : [node];
  const d = useDisclosure(name === "components" || name === "ui");
  if (!isFolder) {
    return (
      <SidebarMenuItem>
        <SidebarMenuButton href="#" size="sm" isActive={name === "button.tsx"}>
          <Icon name={File} size={16} /><span>{name}</span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    );
  }
  return (
    <SidebarMenuItem>
      <SidebarMenuButton size="sm" {...d.triggerProps}>
        <Icon name={ChevronRight} size={16} className={d.open ? "rotate-90 transition-transform" : "transition-transform"} />
        <Icon name={Folder} size={16} />
        <span>{name}</span>
      </SidebarMenuButton>
      <SidebarMenuSub {...d.contentProps} className="me-0 pe-0">
        {children.map((c, i) => <TreeNode key={i} node={c as Node} />)}
      </SidebarMenuSub>
    </SidebarMenuItem>
  );
}

export function AppSidebar() {
  return (
    <Sidebar label="Files">
      <SidebarContent>
        <SidebarGroup>
          <SidebarGroupLabel as="h2">Changes</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {changes.map((c) => (
                <SidebarMenuItem key={c.file}>
                  <SidebarMenuButton href="#" size="sm"><Icon name={File} size={16} /><span>{c.file}</span></SidebarMenuButton>
                  <SidebarMenuBadge label={stateLabel[c.state as keyof typeof stateLabel]} className="top-1.5">{c.state}</SidebarMenuBadge>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
        <SidebarGroup>
          <SidebarGroupLabel as="h2">Files</SidebarGroupLabel>
          <SidebarGroupContent>
            <nav aria-label="Files">
              <SidebarMenu>{tree.map((n, i) => <TreeNode key={i} node={n} />)}</SidebarMenu>
            </nav>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>
      <SidebarRail />
    </Sidebar>
  );
}

"use client";
import type { ReactNode } from "react";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { SidebarTrigger } from "@/components/ui/sidebar";

/** The bar above the page: sidebar toggle, breadcrumbs and optional actions on the end side. */
export function SiteHeader({ crumbs, actions }: { crumbs: { label: string; href?: string }[]; actions?: ReactNode }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4 md:rounded-t-[inherit]">
      <SidebarTrigger className="-ms-1" />
      <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
      <Breadcrumbs items={crumbs} />
      {actions && <div className="ms-auto flex items-center gap-2">{actions}</div>}
    </header>
  );
}

/** Stand-in content for a page. Replace it with your own. */
export function PagePlaceholder({ title }: { title: string }) {
  return (
    <div className="flex flex-1 flex-col gap-4 p-4 md:p-6">
      <h1 className="text-heading-h2">{title}</h1>
      <div aria-hidden className="grid gap-4 md:grid-cols-3">
        <div className="aspect-video rounded-container bg-surface-subtle" />
        <div className="aspect-video rounded-container bg-surface-subtle" />
        <div className="aspect-video rounded-container bg-surface-subtle" />
      </div>
      <div aria-hidden className="min-h-96 flex-1 rounded-container bg-surface-subtle" />
    </div>
  );
}
